[tool error]
{
  "ok": false,
  "name": "draw_offset",
  "error": {
    "type": "invalid_params",
    "message": "'offsets' is a required property",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "alignment": {
          "type": "string",
          "minLength": 1
        },
        "offsets": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": [
              "number",
              "string"
            ]
          },
          "description": "offset distances from the alignment, feet, right of the direction of stationing positive; a string may name the side ('15L', '15R'). A 30 ft pavement is [-15, 15]; add [-21, 21] for 6 ft shoulders."
        },
        "station_range": {
          "type": "array",
          "items": {
            "type": [
              "number",
              "string"
            ],
            "description": "display station: feet (8400) or '84+00.00'"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "draw only between these display stations: how a pavement edge stops at an intersection and picks up again on the far leg"
        },
        "layer": {
          "type": "string",
          "minLength": 1
        },
        "color": {
          "type": "string",
          "description": "named CAD color (black, red, yellow, green, cyan, blue, magenta, gray, white) or '#RRGGBB'"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ]
        },
        "replace": {
          "type": "boolean",
          "description": "delete this alignment's previously drawn offsets at the same distances first (default false); with a station_range, only the pieces inside it"
        }
      },
      "required": [
        "offsets"
      ],
      "additionalProperties": false
    },
    "example": {
      "alignment": "ALIGN-1",
      "offsets": [
        -15,
        15
      ],
      "layer": "rd_EP"
    }
  },
  "warnings": []
}
